    queue.write_texture({.texture = texture, .origin = flight::Array{0.0, (start_row + full_rows), 0.0}}, data, {.offset = ((full_rows * wgpu_skin_arena_width) * 16.0), .bytes_per_row = (remainder * 16.0)}, flight::Array{remainder, 1.0, 1.0});
